// -- DBNO state bools + Encrypted health (STRUCTURAL anchors) --------------
// These fields have NO stable plaintext name (Krafton hashes them, and the hash
// changes between builds), so we DO NOT match them by name. gen_offsets.py finds
// them by structural signature instead (see structural_offsets()):
//   * EncryptedHealth / EncryptedDBNOHealth = the one 0x18 opaque struct type that
//     appears in BOTH TslCharacterBase and TslCharacter (cross-referenced).
//   * The 3 DBNO bools = the run of 3 consecutive bool bytes nearest below
//     EncryptedDBNOHealth (auto-skips the decoy bool triple ~0x200 earlier).
// If a future build reshapes this cluster, the tool emits a // TODO for these.
//
// Names match the reference offset lists: bIsDBNO1 (0x3550, marked USED), bIsDBNO2,
// bIsDBNO0. Each generated line also carries the CURRENT hashed dump name as a sample
// (e.g. TslCharacter::*eee25f8a85) plus the runtime role — reference only; the tool
// does NOT match by the hashed name.
//
// The 3 bools (roles came from runtime state-diff over thousands of snapshots):
//   up    = read<uint8_t>(pawn + bIsDBNO1);  // bUp:        1 = standing (alive & not knocked)
//   alive = read<uint8_t>(pawn + bIsDBNO2);  // bAlive:     1 = alive OR knocked; 0 = fully dead
//   valid = read<uint8_t>(pawn + bIsDBNO0);  // bValidator: ~always 1 on a real pawn -> reject fakes
//   isDead    = (valid && alive == 0);
//   isKnocked = (alive && up == 0);                  // DBNO / crawling
//   isUp      = (up == 1);
// Cross-check isKnocked against DBNOHealth>0 for confidence.
